#!/usr/bin/env bash
# scripts/formula.sh <version> <checksums.txt>: the Homebrew formula of a release.
set -euo pipefail
v="$1"; sums="$2"
sha() { grep "respawn_${v}_$1.tar.gz" "$sums" | cut -d' ' -f1; }
url="https://github.com/matteocodogno/respawn/releases/download/v${v}"
cat <<RUBY
# Generated by scripts/formula.sh at release time: do not edit by hand.
class Respawn < Formula
  desc "Comic-book slide decks as code, with live terminals and a follow-along audience"
  homepage "https://github.com/matteocodogno/respawn"
  version "${v}"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "${url}/respawn_${v}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "${url}/respawn_${v}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "${url}/respawn_${v}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "${url}/respawn_${v}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "respawn"
  end

  def caveats
    <<~EOS
      The PDF export needs Chrome, Chromium, Brave or Edge.
      The audience copy over the internet (respawn serve --tunnel) needs cloudflared:
        brew install cloudflared
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/respawn version")
    system bin/"respawn", "new", "deck"
    system bin/"respawn", "build", "--dir", "deck"
  end
end
RUBY
